-- View for base predicate `InstructionApproved`.
CREATE OR REPLACE VIEW "morpholog_views"."instruction_approved" AS
WITH governed_claims AS (
    SELECT arguments, asserted_in, asserted_at
    FROM morpholog.claims
    WHERE predicate_name = 'InstructionApproved'
)
SELECT
    asserted_in                AS "_morpholog_asserted_in",
    asserted_at                AS "_morpholog_asserted_at",
    arguments                  AS "_morpholog_arguments",
    arguments -> 0 ->> 'value' AS "org",
    arguments -> 1 ->> 'value' AS "instruction",
    arguments -> 2 ->> 'value' AS "approver"
FROM governed_claims;
COMMENT ON VIEW "morpholog_views"."instruction_approved" IS 'Generated by Morpholog; predicate=InstructionApproved';
COMMENT ON COLUMN "morpholog_views"."instruction_approved"."org" IS 'Morpholog kind Subject';
COMMENT ON COLUMN "morpholog_views"."instruction_approved"."instruction" IS 'Morpholog kind Subject';
COMMENT ON COLUMN "morpholog_views"."instruction_approved"."approver" IS 'Morpholog kind Subject';

