-- Seal: each view's definition as PostgreSQL stores it, hashed.
CREATE TABLE IF NOT EXISTS "morpholog_views"."_morpholog_view_defs" (view_name text PRIMARY KEY, definition_sha256 text NOT NULL);
TRUNCATE "morpholog_views"."_morpholog_view_defs";
INSERT INTO "morpholog_views"."_morpholog_view_defs" (view_name, definition_sha256)
SELECT v.name, encode(sha256(convert_to(pg_get_viewdef(format('%I.%I', 'morpholog_views', v.name)::regclass, true), 'UTF8')), 'hex')
FROM ( VALUES
    ('may_capture_trade'::text),
    ('may_register_curve'),
    ('may_value_trade'),
    ('may_set_limit'),
    ('may_instruct'),
    ('may_approve'),
    ('may_grant_authority'),
    ('may_establish_organisations'),
    ('actor_assertion_restricted'),
    ('actor_assertion_authority'),
    ('market_currency'),
    ('trade_captured'),
    ('trade_terms'),
    ('trade_terms_supersedes'),
    ('curve_registered'),
    ('official_curve'),
    ('curve_supersedes'),
    ('trade_valued'),
    ('position_limit'),
    ('instruction'),
    ('instruction_open'),
    ('approval_required'),
    ('instruction_approved'),
    ('instruction_ended'),
    ('_morpholog_catalog')
) AS v(name);

COMMIT;
